// Serves the web UI and a small JSON API. Data rules live in lib/store.js.

import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { Store } from './lib/store.js';
import { lookupTitle, capturePage } from './lib/fetchpage.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PORT = process.env.PORT ? Number(process.env.PORT) : 4000;
const HOST = '0.0.0.0';
const DATA_DIR = process.env.DATA_DIR || path.join(__dirname, 'data');
const PUBLIC_DIR = path.join(__dirname, 'public');

const store = new Store(DATA_DIR);

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
};

function sendJson(res, status, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(body);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', c => {
      data += c;
      if (data.length > 5 * 1024 * 1024) { reject(new Error('body too large')); req.destroy(); }
    });
    req.on('end', () => {
      if (!data) return resolve({});
      try { resolve(JSON.parse(data)); } catch { reject(new Error('bad json')); }
    });
    req.on('error', reject);
  });
}

function serveStatic(req, res, urlPath) {
  let rel = urlPath === '/' ? '/index.html' : urlPath;
  const filePath = path.normalize(path.join(PUBLIC_DIR, rel));
  if (!filePath.startsWith(PUBLIC_DIR)) { res.writeHead(403); return res.end('Forbidden'); }
  fs.readFile(filePath, (err, buf) => {
    if (err) { res.writeHead(404); return res.end('Not found'); }
    const ext = path.extname(filePath).toLowerCase();
    res.writeHead(200, { 'Content-Type': MIME[ext] || 'application/octet-stream' });
    res.end(buf);
  });
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const p = url.pathname;

  try {
    // --- API ---
    if (p === '/api/bookmarks' && req.method === 'GET') {
      return sendJson(res, 200, { bookmarks: store.list() });
    }

    if (p === '/api/bookmarks' && req.method === 'POST') {
      const body = await readBody(req);
      const result = store.create(body);
      if (result.error === 'empty') return sendJson(res, 400, { error: 'empty', message: 'Please enter a link address first.' });
      if (result.error === 'invalid') return sendJson(res, 400, { error: 'invalid', message: "That doesn't look like a valid web address. Please check it." });
      if (result.error === 'duplicate') return sendJson(res, 409, { error: 'duplicate', existing: result.existing, message: "You already saved this link. It won't be saved twice." });
      // SCN-005: capture snapshot when a copy was requested.
      if (result.bookmark.keepcopy) {
        const cap = await capturePage(result.bookmark.url);
        store.setSnapshot(result.bookmark.id, JSON.stringify({
          capturedAt: result.bookmark.savedOn,
          ok: cap.ok,
          title: cap.title || result.bookmark.title,
          text: cap.ok ? cap.text : '',
        }));
      }
      return sendJson(res, 201, { bookmark: result.bookmark });
    }

    const idMatch = p.match(/^\/api\/bookmarks\/(\d+)$/);
    if (idMatch) {
      const id = Number(idMatch[1]);
      if (req.method === 'PUT') {
        const body = await readBody(req);
        const before = store.get(id);
        const wasCopy = before && before.keepcopy;
        const result = store.update(id, body);
        if (result.error === 'notfound') return sendJson(res, 404, { error: 'notfound' });
        if (result.error === 'invalid') return sendJson(res, 400, { error: 'invalid', message: "That doesn't look like a valid web address." });
        if (result.error === 'duplicate') return sendJson(res, 409, { error: 'duplicate', existing: result.existing, message: 'Another saved link already uses that address.' });
        // Refresh snapshot if a copy is now wanted and none stored, or address changed.
        const bm = result.bookmark;
        if (bm.keepcopy && (!wasCopy || (body.url !== undefined))) {
          const cap = await capturePage(bm.url);
          store.setSnapshot(bm.id, JSON.stringify({
            capturedAt: bm.savedOn, ok: cap.ok,
            title: cap.title || bm.title, text: cap.ok ? cap.text : '',
          }));
        }
        return sendJson(res, 200, { bookmark: bm });
      }
      if (req.method === 'DELETE') {
        const result = store.remove(id);
        if (result.error) return sendJson(res, 404, { error: 'notfound' });
        return sendJson(res, 200, { ok: true });
      }
    }

    const snapMatch = p.match(/^\/api\/snapshot\/(\d+)$/);
    if (snapMatch && req.method === 'GET') {
      const raw = store.getSnapshot(snapMatch[1]);
      if (!raw) return sendJson(res, 404, { error: 'nosnapshot' });
      return sendJson(res, 200, JSON.parse(raw));
    }

    if (p === '/api/lookup-title' && req.method === 'GET') {
      const target = url.searchParams.get('url') || '';
      const r = await lookupTitle(target);
      return sendJson(res, 200, { title: r.title, ok: r.ok });
    }

    // --- Static ---
    if (req.method === 'GET') return serveStatic(req, res, p);

    res.writeHead(405); res.end('Method not allowed');
  } catch (e) {
    sendJson(res, 400, { error: 'badrequest', message: String(e && e.message || e) });
  }
});

server.listen(PORT, HOST, () => {
  console.log(`Bookmark Keeper listening on http://${HOST}:${PORT}`);
});

export { server, store };
// Durable storage for bookmarks (SCN-011: persist between visits).
// Bookmarks are kept in a JSON file; kept-copy snapshots are stored as separate
// HTML files. This module owns all data rules (create/edit/remove, duplicate
// rejection); the HTTP layer and network fetching live in server.js.

import fs from 'node:fs';
import path from 'node:path';
import { normalizeUrl, isValidUrl, sameUrl, normalizeTags } from './validate.js';

export class Store {
  constructor(dataDir) {
    this.dataDir = dataDir;
    this.dbFile = path.join(dataDir, 'bookmarks.json');
    this.snapDir = path.join(dataDir, 'snapshots');
    fs.mkdirSync(this.snapDir, { recursive: true });
    this._load();
  }

  _load() {
    try {
      const raw = fs.readFileSync(this.dbFile, 'utf8');
      const parsed = JSON.parse(raw);
      this.items = Array.isArray(parsed.items) ? parsed.items : [];
      this.nextId = parsed.nextId || this._maxId() + 1;
    } catch {
      this.items = [];
      this.nextId = 1;
    }
  }

  _maxId() {
    return this.items.reduce((m, it) => Math.max(m, it.id || 0), 0);
  }

  _save() {
    const tmp = this.dbFile + '.tmp';
    fs.writeFileSync(tmp, JSON.stringify({ items: this.items, nextId: this.nextId }, null, 2));
    fs.renameSync(tmp, this.dbFile); // atomic replace
  }

  // Newest first (SCN-001).
  list() {
    return this.items.slice().sort((a, b) => b.createdAt - a.createdAt || b.id - a.id);
  }

  get(id) {
    return this.items.find(it => it.id === Number(id)) || null;
  }

  findByUrl(url, exceptId = null) {
    return this.items.find(it => sameUrl(it.url, url) && it.id !== Number(exceptId)) || null;
  }

  // data: { url, title, note, tags, toread, keepcopy }
  // Returns { bookmark } or { error, existing }.
  create(data) {
    const url = normalizeUrl(data.url);
    if (!url) return { error: 'empty' };
    if (!isValidUrl(url)) return { error: 'invalid' };
    const existing = this.findByUrl(url);
    if (existing) return { error: 'duplicate', existing }; // SCN-007

    const bm = {
      id: this.nextId++,
      url,
      title: (data.title || '').trim(),
      note: (data.note || '').trim(),
      tags: normalizeTags(data.tags),
      toread: data.toread !== false,          // SCN-004: default to "to read"
      keepcopy: !!data.keepcopy,              // SCN-005: opt-in
      savedOn: data.keepcopy ? new Date().toISOString() : null,
      createdAt: Date.now(),
    };
    this.items.push(bm);
    this._save();
    return { bookmark: bm };
  }

  // Partial update. Validates address changes the same way as create (SCN-006).
  update(id, data) {
    const bm = this.get(id);
    if (!bm) return { error: 'notfound' };

    if (data.url !== undefined) {
      const url = normalizeUrl(data.url);
      if (!isValidUrl(url)) return { error: 'invalid' };
      const clash = this.findByUrl(url, bm.id);
      if (clash) return { error: 'duplicate', existing: clash };
      bm.url = url;
    }
    if (data.title !== undefined) bm.title = (data.title || '').trim();
    if (data.note !== undefined) bm.note = (data.note || '').trim();
    if (data.tags !== undefined) bm.tags = normalizeTags(data.tags);
    if (data.toread !== undefined) bm.toread = !!data.toread;
    if (data.keepcopy !== undefined) {
      bm.keepcopy = !!data.keepcopy;
      if (bm.keepcopy && !bm.savedOn) bm.savedOn = new Date().toISOString();
    }
    this._save();
    return { bookmark: bm };
  }

  remove(id) {
    const i = this.items.findIndex(it => it.id === Number(id));
    if (i === -1) return { error: 'notfound' };
    this.items.splice(i, 1);
    this._save();
    this._deleteSnapshot(id);
    return { ok: true };
  }

  // Snapshot storage (SCN-005). Content is the readable page text captured at save.
  setSnapshot(id, content) {
    fs.writeFileSync(path.join(this.snapDir, `${id}.html`), content, 'utf8');
  }

  getSnapshot(id) {
    try {
      return fs.readFileSync(path.join(this.snapDir, `${id}.html`), 'utf8');
    } catch {
      return null;
    }
  }

  _deleteSnapshot(id) {
    try { fs.unlinkSync(path.join(this.snapDir, `${id}.html`)); } catch { /* none */ }
  }
}
// Address and tag normalisation / validation.
// Basis: SCN-008 (invalid/empty address, missing-scheme forgiveness),
//        SCN-002/SCN-006 (tag lower-casing and de-duplication),
//        SCN-007 (duplicate detection by address, ignoring trailing slash).

export function normalizeUrl(raw) {
  let s = (raw || '').trim();
  if (!s) return '';
  if (!/^https?:\/\//i.test(s)) s = 'https://' + s; // SCN-008: forgive missing scheme
  return s;
}

export function isValidUrl(u) {
  try {
    const p = new URL(u);
    return (p.protocol === 'http:' || p.protocol === 'https:')
      && !!p.hostname && p.hostname.includes('.');
  } catch {
    return false;
  }
}

// Canonical form for duplicate comparison: ignore a trailing slash (SCN-007).
export function canonicalUrl(u) {
  return (u || '').replace(/\/+$/, '');
}

export function sameUrl(a, b) {
  return canonicalUrl(a) === canonicalUrl(b);
}

export function normalizeTag(t) {
  return (t || '').trim().replace(/^#/, '').toLowerCase();
}

export function normalizeTags(tags) {
  const out = [];
  for (const raw of (tags || [])) {
    const t = normalizeTag(raw);
    if (t && !out.includes(t)) out.push(t); // lower-cased + de-duplicated
  }
  return out;
}

// Parse a comma-separated tag string (used by the edit form).
export function parseTagString(s) {
  return normalizeTags((s || '').split(','));
}

export function hostOf(u) {
  try {
    return new URL(u).hostname.replace(/^www\./, '');
  } catch {
    return '';
  }
}
// Real page access for title lookup (SCN-001) and safety-net snapshots (SCN-005).
// External network access may be unavailable; every function degrades gracefully
// and never throws to the caller.

const UA = 'Mozilla/5.0 (compatible; BookmarkKeeper/1.0)';
const TIMEOUT_MS = 8000;
const MAX_BYTES = 3 * 1024 * 1024;

async function fetchText(url) {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), TIMEOUT_MS);
  try {
    const res = await fetch(url, { headers: { 'User-Agent': UA }, signal: ctrl.signal, redirect: 'follow' });
    if (!res.ok) return { ok: false, status: res.status };
    const reader = res.body?.getReader();
    if (!reader) {
      const text = await res.text();
      return { ok: true, text: text.slice(0, MAX_BYTES) };
    }
    let received = 0;
    const chunks = [];
    // Read up to MAX_BYTES so a huge page can't exhaust memory.
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      received += value.length;
      chunks.push(value);
      if (received >= MAX_BYTES) { ctrl.abort(); break; }
    }
    const buf = Buffer.concat(chunks.map(c => Buffer.from(c)));
    return { ok: true, text: buf.toString('utf8') };
  } catch (e) {
    return { ok: false, error: String(e && e.message || e) };
  } finally {
    clearTimeout(timer);
  }
}

function decodeEntities(s) {
  return s
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ')
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)));
}

export function extractTitle(html) {
  const m = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  if (!m) return '';
  return decodeEntities(m[1]).replace(/\s+/g, ' ').trim();
}

// Reduce an HTML page to readable text for the kept copy.
export function extractReadableText(html) {
  let s = html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<\/(p|div|section|article|h[1-6]|li|br)>/gi, '\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, ' ');
  s = decodeEntities(s).replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
  return s;
}

// Returns { title } — empty string if it couldn't be fetched.
export async function lookupTitle(url) {
  const r = await fetchText(url);
  if (!r.ok || !r.text) return { title: '', ok: false };
  return { title: extractTitle(r.text), ok: true };
}

// Returns { ok, title, text } for storing a snapshot.
export async function capturePage(url) {
  const r = await fetchText(url);
  if (!r.ok || !r.text) return { ok: false, title: '', text: '' };
  return { ok: true, title: extractTitle(r.text), text: extractReadableText(r.text) };
}
