<body>
<header>
  <h1>My Bookmarks</h1>
  <p>Prototype for exploration — not the final product.</p>
</header>
<div class="wrap">
  <div class="panel">
    <h2>Save a link</h2>
    <label for="url">Link address</label>
    <input type="url" id="url" placeholder="https://example.com/article" />
    <label for="title">Title <span id="titleStatus" style="color:var(--muted);font-weight:normal"></span></label>
    <input type="text" id="title" placeholder="Fills in automatically from the page — edit if you like" />
    <label for="tagInput">Tags</label>
    <div id="tagBox" style="display:flex;flex-wrap:wrap;gap:6px;align-items:center;border:1px solid var(--line);border-radius:8px;padding:6px 8px;">
      <span id="tagChips" style="display:flex;flex-wrap:wrap;gap:6px;"></span>
      <input type="text" id="tagInput" placeholder="Type a tag, press Enter" style="border:none;outline:none;flex:1;min-width:140px;padding:4px;font-size:14px;" />
    </div>
    <label for="note">Why are you saving this? (optional)</label>
    <textarea id="note" placeholder="e.g. Good explanation of X — read before the Tuesday meeting"></textarea>
    <label style="display:flex;align-items:center;gap:8px;margin-top:12px;cursor:pointer;font-size:14px;color:var(--ink);">
      <input type="checkbox" id="toread" checked /> I still want to read this
    </label>
    <label style="display:flex;align-items:center;gap:8px;margin-top:8px;cursor:pointer;font-size:14px;color:var(--ink);">
      <input type="checkbox" id="keepcopy" /> Keep a copy in case this page disappears
    </label>
    <div class="row-btn"><button class="primary" id="saveBtn">Save link</button></div>
    <div id="formMsg" style="margin-top:12px;font-size:13px;"></div>
  </div>

  <div class="panel">
    <h2>Saved links</h2>
    <input type="text" id="search" placeholder="Search your links…" style="width:100%;padding:10px 12px;border:1px solid var(--line);border-radius:8px;font-size:14px;margin-bottom:12px;" />
    <div id="readTabs" style="display:flex;gap:6px;margin-bottom:12px;"></div>
    <div id="filterBar" style="margin-bottom:12px;"></div>
    <div class="count" id="count"></div>
    <div id="list"></div>
  </div>
</div>

<script>
  const items = [];
  let pendingTags = [];     // tags being attached to the link currently being saved
  let activeFilter = null;  // tag currently used to narrow the list
  let readView = 'all';     // 'all' | 'toread' | 'read'
  let nextId = 1;
  let editingId = null;     // id of the link currently being edited

  function flashItem(el){ el.classList.remove('flash'); void el.offsetWidth; el.classList.add('flash'); }
  const listEl = document.getElementById('list');
  const countEl = document.getElementById('count');

  function hostOf(u){ try { return new URL(u).hostname.replace(/^www\./,''); } catch(e){ return ''; } }

  // --- Simulated title lookup (prototype only) ---------------------------
  // The real app would fetch the page's title. Here we fabricate a plausible
  // title from the URL so the auto-fill behaviour can be experienced.
  const titleEl = () => document.getElementById('title');
  const statusEl = () => document.getElementById('titleStatus');
  let titleWasEdited = false;

  function simulateTitle(url){
    const host = hostOf(url);
    if(!host) return null;
    let slug = '';
    try {
      const p = new URL(url).pathname.replace(/\/+$/,'').split('/').filter(Boolean).pop() || '';
      slug = p.replace(/[-_]+/g,' ').replace(/\.[a-z0-9]+$/i,'').trim();
    } catch(e){}
    const brand = host.split('.')[0].replace(/^\w/, c => c.toUpperCase());
    if(slug){
      const nice = slug.replace(/\b\w/g, c => c.toUpperCase());
      return nice + ' — ' + brand;
    }
    return brand + ' — Home';
  }

  function lookupTitle(){
    const url = document.getElementById('url').value.trim();
    if(!url) return;
    if(titleWasEdited && titleEl().value) return; // don't overwrite user edits
    statusEl().textContent = '· looking up…';
    setTimeout(() => {
      const t = simulateTitle(url);
      statusEl().textContent = t ? '· filled in automatically' : '';
      if(t && !titleWasEdited){ titleEl().value = t; }
    }, 600);
  }

  document.getElementById('url').addEventListener('blur', lookupTitle);

  function renderPendingTags(){
    const chips = document.getElementById('tagChips');
    chips.innerHTML = '';
    pendingTags.forEach((t, i) => {
      const span = document.createElement('span');
      span.className = 'tag';
      span.innerHTML = '#'+t+' <button title="remove" data-i="'+i+'">×</button>';
      span.querySelector('button').addEventListener('click', () => {
        pendingTags.splice(i,1); renderPendingTags();
      });
      chips.appendChild(span);
    });
  }

  function addPendingTag(raw){
    const t = raw.trim().replace(/^#/,'').toLowerCase();
    if(t && !pendingTags.includes(t)) pendingTags.push(t);
    renderPendingTags();
  }

  function allTags(){
    const set = new Set();
    items.forEach(it => (it.tags||[]).forEach(t => set.add(t)));
    return Array.from(set).sort();
  }

  function renderFilterBar(){
    const bar = document.getElementById('filterBar');
    const tags = allTags();
    if(tags.length === 0){ bar.innerHTML = ''; return; }
    bar.innerHTML = '<span class="filter-note">Filter by tag: </span>';
    const holder = document.createElement('span');
    holder.style.cssText = 'display:inline-flex;flex-wrap:wrap;gap:6px;margin-left:4px;';
    tags.forEach(t => {
      const span = document.createElement('span');
      span.className = 'tag click' + (activeFilter === t ? ' active' : '');
      span.textContent = '#'+t;
      span.addEventListener('click', () => {
        activeFilter = (activeFilter === t) ? null : t;
        render();
      });
      holder.appendChild(span);
    });
    bar.appendChild(holder);
    if(activeFilter){
      const clear = document.createElement('span');
      clear.className = 'filter-note';
      clear.style.cssText = 'margin-left:10px;cursor:pointer;text-decoration:underline;';
      clear.textContent = 'clear filter';
      clear.addEventListener('click', () => { activeFilter = null; render(); });
      bar.appendChild(clear);
    }
  }

  function confirmDelete(it, div){
    const actions = div.querySelector('.actions');
    actions.innerHTML = '<span class="msg-warn" style="display:inline-block">Remove "'+
      (it.title||it.url)+'"? <button data-yes>Remove</button> '+
      '<button data-no style="background:#eee;color:#333">Keep</button></span>';
    actions.querySelector('[data-yes]').addEventListener('click', () => {
      const i = items.findIndex(x => x.id === it.id);
      if(i > -1) items.splice(i,1);
      render();
    });
    actions.querySelector('[data-no]').addEventListener('click', render);
  }

  function showSavedCopy(it){
    // Prototype only: fabricate a preserved snapshot so the "saved copy" idea
    // can be experienced. The real app would store the actual page content.
    const title = it.title || it.url;
    const ov = document.createElement('div');
    ov.className = 'overlay';
    ov.innerHTML =
      '<div class="snap">' +
        '<div class="bar"><span>Saved copy — captured on '+(it.savedOn||'the day you saved it')+
          '. This is your kept copy, shown even if the original page is gone.</span>' +
          '<button id="closeSnap">Close</button></div>' +
        '<div class="body">' +
          '<h3>'+title+'</h3>' +
          '<div class="src">Originally from '+hostOf(it.url)+'</div>' +
          '<p>(Simulated preserved content for this exploration.) This is a copy of the ' +
          'page as it looked when you saved it, so the information stays available to you ' +
          'even if the original later changes or disappears.</p>' +
          '<p>The real app would keep the actual readable text and key content of the page here.</p>' +
        '</div>' +
      '</div>';
    ov.addEventListener('click', (e) => { if(e.target === ov) ov.remove(); });
    document.body.appendChild(ov);
    document.getElementById('closeSnap').addEventListener('click', () => ov.remove());
  }

  function matchesSearch(it, q){
    if(!q) return true;
    const hay = [it.title, it.note, it.url, (it.tags||[]).join(' ')].join(' ').toLowerCase();
    return q.toLowerCase().split(/\s+/).filter(Boolean).every(term => hay.includes(term));
  }

  function renderReadTabs(){
    const el = document.getElementById('readTabs');
    const toReadCount = items.filter(it => it.toread).length;
    const tabs = [
      ['all','All'],
      ['toread','To read ('+toReadCount+')'],
      ['read','Read']
    ];
    el.innerHTML = '';
    tabs.forEach(([key,label]) => {
      const b = document.createElement('button');
      b.className = 'rtab' + (readView===key ? ' active' : '');
      b.textContent = label;
      b.addEventListener('click', () => { readView = key; render(); });
      el.appendChild(b);
    });
  }

  function render(){
    renderReadTabs();
    renderFilterBar();
    const q = (document.getElementById('search').value || '').trim();
    let shown = activeFilter ? items.filter(it => (it.tags||[]).includes(activeFilter)) : items;
    if(readView === 'toread') shown = shown.filter(it => it.toread);
    else if(readView === 'read') shown = shown.filter(it => !it.toread);
    shown = shown.filter(it => matchesSearch(it, q));
    const desc = (activeFilter ? ' tagged #'+activeFilter : '') + (q ? ' matching "'+q+'"' : '');
    countEl.textContent = (shown.length === 1 ? '1 saved link' : shown.length + ' saved links') + desc;
    if(shown.length === 0){
      let msg;
      if(items.length === 0) msg = 'No links saved yet. Save your first one above.';
      else if(q) msg = 'No links match your search'+(activeFilter ? ' within #'+activeFilter : '')+'.';
      else msg = 'No links tagged #'+activeFilter+'.';
      listEl.innerHTML = '<div class="empty">'+msg+'</div>';
      return;
    }
    listEl.innerHTML = '';
    shown.forEach(it => {
      const div = document.createElement('div');
      div.className = 'item' + (it.toread ? '' : ' read');
      div.setAttribute('data-item', it.id);

      if(editingId === it.id){
        div.innerHTML =
          '<div class="edit-field"><label>Link address</label>' +
            '<input type="url" id="e-url" value="'+ (it.url||'').replace(/"/g,'&quot;') +'"></div>' +
          '<div class="edit-field"><label>Title</label>' +
            '<input type="text" id="e-title" value="'+ (it.title||'').replace(/"/g,'&quot;') +'"></div>' +
          '<div class="edit-field"><label>Why are you saving this?</label>' +
